213	  <script>
214	    (function () {
215	      var html = document.documentElement;
216	
217	      /* Surface token convention: internal stylesheet uses unprefixed names. */
218	      var PREFIX = '';
219	      var STATES = [['Success','success'], ['Info','info'], ['Warning','warning'], ['Error / failure','error']];
220	
221	      function readVar(name) { return getComputedStyle(html).getPropertyValue(name).trim(); }
222	      function toRGB(value) {
223	        var probe = document.createElement('span');
224	        probe.style.color = value;
225	        document.body.appendChild(probe);
226	        var rgb = getComputedStyle(probe).color;
227	        probe.remove();
228	        return rgb.match(/[\d.]+/g).slice(0, 3).map(Number);
229	      }
230	      function hex(c) { return '#' + c.map(function (x) { return Math.round(x).toString(16).padStart(2, '0'); }).join(''); }
231	      function lum(c) {
232	        var f = c.map(function (v) { v /= 255; return v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4); });
233	        return 0.2126 * f[0] + 0.7152 * f[1] + 0.0722 * f[2];
234	      }
235	      function ratio(a, b) { var L1 = lum(a), L2 = lum(b), hi = Math.max(L1, L2), lo = Math.min(L1, L2); return (hi + 0.05) / (lo + 0.05); }
236	      function grade(r) { return r >= 7 ? 'AAA' : r >= 4.5 ? 'AA' : r >= 3 ? 'AA Large' : null; }
237	      function cell(c) { return '<span class="swatch" style="background:' + hex(c) + '"></span><code>' + hex(c) + '</code>'; }
238	
239	      function render() {
240	        var rows = STATES.map(function (s) {
241	          var bg = toRGB(readVar('--' + PREFIX + s[1] + '-bg'));
242	          var bd = toRGB(readVar('--' + PREFIX + s[1] + '-border'));
243	          var fg = toRGB(readVar('--' + PREFIX + s[1] + '-fg'));
244	          var r = ratio(fg, bg), g = grade(r);
245	          var label = g ? '<span class="ratio-pass">' + r.toFixed(1) + ':1 ✓ ' + g + '</span>'
246	                        : '<span class="ratio-fail">' + r.toFixed(1) + ':1 ✗</span>';
247	          return '<tr><td class="state-name">' + s[0] + '</td><td>' + cell(bg) + '</td><td>' + cell(bd) + '</td><td>' + cell(fg) + '</td><td>' + label + '</td></tr>';
248	        }).join('');
249	        document.getElementById('token-rows').innerHTML = rows;
250	      }
251	
252	      render();
253	      /* Re-read if the OS flips light/dark while the page is open. */
254	      window.matchMedia('(prefers-color-scheme: dark)').addEventListener('change', render);
255	    })();
256	  </script>
257	</body>
258	</html>
